#!/usr/bin/env python3
"""
ABRAXAS PRODUCT UPGRADE SCRIPT
Run from project root: python3 fix_product.py

Delivers:
  - Rebuilt PortfolioTab (protocol flow hero, signal feed, correct hierarchy)
  - Institutional BorrowPage
  - ProtocolFlow component (VERIFY→TOKENIZE→COLLATERALIZE→BORROW→CREDIT)
  - TerminalArena with auth link + Sign In visible
  - app/page.tsx + layout.tsx with SessionProvider
  - LanguageSelector + CompactWallet
  - vercel.json with 1x daily cron (Hobby plan compatible)
  - Fixed bags cron route
"""
import base64, os, sys

if not os.path.exists("app"):
    print("Run from project root"); sys.exit(1)

FILES = {
    "components/PortfolioTab.tsx": "",
    "components/BorrowPage.tsx": "",
    "components/ProtocolFlow.tsx": "",
    "components/TerminalArena.tsx": "",
    "app/page.tsx": "",
    "app/layout.tsx": "",
    "components/LanguageSelector.tsx": "",
    "components/CompactWallet.tsx": "",
    "vercel.json": "",
    "app/api/cron/bags-sync/route.ts": "",
}

for path, enc in FILES.items():
    d = os.path.dirname(path)
    if d: os.makedirs(d, exist_ok=True)
    content = base64.b64decode(enc).decode("utf-8")
    with open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"WRITTEN  {path} ({len(content.splitlines())} lines)")

print("""
All files written.

npm run build
git add -A
git commit -m "feat: product upgrade — protocol flow hero, signal feed, borrow page, UI hierarchy"
git push origin main
""")
